package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

// completionsDir holds shell completion scripts generated by apply. ~/.bashrc
// and ~/.zshrc source them at startup.
func completionsDir(homeDir string) string {
	return filepath.Join(homeDir, ".cache", "dotfiles", "completions")
}

// ensureCompletions caches `kubectl completion <shell>`. Generating it takes
// ~80ms (kubectl's startup), sourcing the file ~1ms. It is loaded eagerly
// because the `k` alias is completed by __start_kubectl, and bash-completion's
// lazy loader keys on the typed command name, so it never loads kubectl's
// script for `k` (#13). Regenerated on every apply, so a kubectl upgrade is
// picked up by the next apply (the sandboxes apply daily, users with `dotfiles
// update`). kubectl itself is not a managed tool; without it nothing happens.
// Failures are warnings: a missing completion must not fail apply.
func ensureCompletions(homeDir, shell, command string) {
	if _, err := exec.LookPath("kubectl"); err != nil {
		return
	}
	shells := []string{"bash"}
	if shell == "zsh" {
		shells = append(shells, "zsh")
	}
	for _, sh := range shells {
		path := filepath.Join(completionsDir(homeDir), "kubectl."+sh)
		if command == "diff" {
			if _, err := os.Stat(path); err != nil {
				fmt.Printf("+ %s (kubectl completion %s)\n", tildePath(path), sh)
			}
			continue
		}
		out, err := exec.Command("kubectl", "completion", sh).Output()
		if err != nil || len(out) == 0 {
			fmt.Printf("⚠️ kubectl completion %s failed: %v\n", sh, err)
			continue
		}
		changed, err := writeGenerated(path, out)
		if err != nil {
			fmt.Printf("⚠️ could not write %s: %v\n", path, err)
			continue
		}
		if changed {
			fmt.Printf("✅ Applied %s\n", path)
		} else {
			fmt.Printf("   unchanged %s\n", path)
		}
	}
}

// writeGenerated writes content to path atomically (a failed run never leaves
// a truncated script) and reports whether it changed.
func writeGenerated(path string, content []byte) (bool, error) {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, content) {
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return false, err
	}
	if err := writeFileAtomic(path, content, 0644); err != nil {
		return false, err
	}
	return true, nil
}
